class Solution {
public:
    TreeNode* lcaDeepestLeaves(TreeNode* root) {
        auto dfs = [&](auto& self, TreeNode* node) -> pair<TreeNode*, int> {
            if (!node) return {nullptr, 0};
            auto [l_node, l_depth] = self(self, node->left);
            auto [r_node, r_depth] = self(self, node->right);
            if (l_depth == r_depth) {
                return {node, l_depth + 1};
            } else if (l_depth > r_depth) {
                return {l_node, l_depth + 1};
            } else {
                return {r_node, r_depth + 1};
            }
        };
        return dfs(dfs, root).first;
    }
};

class Solution {
    static class Result {
        TreeNode node;
        int depth;
        Result(TreeNode node, int depth) {
            this.node = node;
            this.depth = depth;
        }
    }

    Result dfs(TreeNode node) {
        if (node == null) return new Result(null, 0);
        Result left = dfs(node.left);
        Result right = dfs(node.right);
        if (left.depth == right.depth) {
            return new Result(node, left.depth + 1);
        } else if (left.depth > right.depth) {
            return new Result(left.node, left.depth + 1);
        } else {
            return new Result(right.node, right.depth + 1);
        }
    }

    public TreeNode lcaDeepestLeaves(TreeNode root) {
        return dfs(root).node;
    }
}

var lcaDeepestLeaves = function(root) {
    const dfs = (node) => {
        if (!node) return [null, 0];
        const [lNode, lDepth] = dfs(node.left);
        const [rNode, rDepth] = dfs(node.right);
        if (lDepth === rDepth) {
            return [node, lDepth + 1];
        } else if (lDepth > rDepth) {
            return [lNode, lDepth + 1];
        } else {
            return [rNode, rDepth + 1];
        }
    };
    return dfs(root)[0];
};
